package main

import (
	"encoding/json"
	"fmt"
	"io/ioutil"
	"net/http"
	"strings"
	"time"

	"github.com/gin-gonic/gin"
)

type MetadataResponse struct {
	InstanceID string `json:"instance_id"`
	Region     string `json:"region"`
	Role       string `json:"iam_role"`
	Token      string `json:"token,omitempty"`
}

type WebhookPayload struct {
	CallbackURL string `json:"callback_url"`
	EventType   string `json:"event_type"`
	Data        string `json:"data"`
}

func main() {
	r := gin.Default()

	// Internal metadata proxy - fetches cloud metadata for service discovery
	r.GET("/api/v1/metadata", func(c *gin.Context) {
		resp, err := http.Get("http://169.254.169.254/latest/meta-data/")
		if err != nil {
			c.JSON(500, gin.H{"error": "metadata unavailable"})
			return
		}
		defer resp.Body.Close()
		body, _ := ioutil.ReadAll(resp.Body)
		c.JSON(200, gin.H{"metadata": string(body)})
	})

	// Webhook notification endpoint - sends event confirmations
	r.POST("/api/v1/webhooks/notify", func(c *gin.Context) {
		var payload WebhookPayload
		if err := c.ShouldBindJSON(&payload); err != nil {
			c.JSON(400, gin.H{"error": "invalid payload"})
			return
		}

		// Basic URL validation - only allow HTTPS callbacks
		if !strings.HasPrefix(payload.CallbackURL, "https://") {
			c.JSON(400, gin.H{"error": "callback must use HTTPS"})
			return
		}

		// Resolve and validate the callback host at request time
		// Note: This check happens BEFORE the actual request
		callbackHost := extractHost(payload.CallbackURL)
		if isInternalIP(callbackHost) {
			c.JSON(403, gin.H{"error": "internal addresses not allowed"})
			return
		}

		// Async callback delivery with retry
		go deliverWebhook(payload)

		c.JSON(202, gin.H{"status": "accepted", "event": payload.EventType})
	})

	// Health check for k8s probes
	r.GET("/healthz", func(c *gin.Context) {
		c.JSON(200, gin.H{"status": "healthy"})
	})

	r.Run(":8080")
}

func extractHost(url string) string {
	// Strip scheme
	noScheme := strings.TrimPrefix(url, "https://")
	noScheme = strings.TrimPrefix(noScheme, "http://")
	// Get host part
	parts := strings.SplitN(noScheme, "/", 2)
	hostPort := strings.SplitN(parts[0], ":", 2)
	return hostPort[0]
}

func isInternalIP(host string) bool {
	// Check against known internal ranges at DNS resolution time
	addrs, err := net.LookupHost(host)
	if err != nil {
		return false
	}
	for _, addr := range addrs {
		if strings.HasPrefix(addr, "10.") ||
			strings.HasPrefix(addr, "172.16.") ||
			strings.HasPrefix(addr, "192.168.") ||
			strings.HasPrefix(addr, "169.254.") ||
			addr == "127.0.0.1" {
			return true
		}
	}
	return false
}

func deliverWebhook(payload WebhookPayload) {
	// Small delay before delivery (window for DNS rebinding)
	time.Sleep(2 * time.Second)

	client := &http.Client{Timeout: 10 * time.Second}

	confirmation := map[string]string{
		"event_type": payload.EventType,
		"status":     "delivered",
		"timestamp":  time.Now().UTC().Format(time.RFC3339),
		"data":       payload.Data,
	}
	jsonBody, _ := json.Marshal(confirmation)

	// DNS is re-resolved here - TOCTOU vulnerability
	resp, err := client.Post(payload.CallbackURL, "application/json",
		strings.NewReader(string(jsonBody)))
	if err != nil {
		fmt.Printf("webhook delivery failed: %v\n", err)
		return
	}
	defer resp.Body.Close()

	body, _ := ioutil.ReadAll(resp.Body)
	fmt.Printf("webhook delivered, response: %s\n", string(body))
}
